// NAME: Draggable Pets
// AUTHORS: nephren
// DESCRIPTION: Draggable animated GIF characters: Sonic, Tails and Shadow on the playback bar, the cat, Miku and Ambers on the home page, Tanjiro in the search bar.
//   A settings panel lets you hide and resize them. Miku sits on the top-right tile of the home page shortcuts grid, Ambers in the top-right corner of the Main frame.
//   Drag = move | double-click = back to the default position | right-click a character or Ctrl+Alt+P = settings panel (show/hide, sizes, reset).
//   Settings are stored in localStorage ("tui-pets-v1"). The GIFs are embedded below (the three pixel-art characters were reduced to their native size, losslessly).
//   The characters are drawn only by this extension: user.css does not draw them any more (keeping both would show every character twice).

(function draggablePets() {
	if (!document.body || !document.head) {
		setTimeout(draggablePets, 200);
		return;
	}
	if (window.tuiPets) return;

	const STORE = "tui-pets-v1";
	const DATA = {
		sonic: "data:image/gif;base64,",
		tails: "data:image/gif;base64,",
		shadow: "data:image/gif;base64,",
		cat: "data:image/gif;base64,",
		miku: "data:image/gif;base64,",
		tanjiro: "data:image/gif;base64,",
		ambers: "data:image/gif;base64,"
	};
	// w / h: size in px at 100% scale (same pixel scale for Sonic, Tails and Shadow)
	const PETS = [
		{ id: "shadow", label: "Shadow", w: 46, h: 40, pixel: true, scaleKey: "scaleSprites" },
		{ id: "tails", label: "Tails", w: 48, h: 39, pixel: true, scaleKey: "scaleSprites" },
		{ id: "sonic", label: "Sonic", w: 40, h: 40, pixel: true, scaleKey: "scaleSprites" },
		{ id: "cat", label: "Cat (home)", w: 101, h: 80, pixel: false, homeOnly: true, scaleKey: "scaleCat" },
		{ id: "miku", label: "Miku (home)", w: 88, h: 88, pixel: false, homeOnly: true, scaleKey: "scaleMiku" },
		{ id: "tanjiro", label: "Tanjiro (search bar)", w: 91, h: 48, pixel: false, scaleKey: "scaleTanjiro" },
		{ id: "ambers", label: "Ambers (home)", w: 82, h: 120, pixel: false, homeOnly: true, scaleKey: "scaleAmbers" }
	];
	const BY_ID = {};
	PETS.forEach(p => (BY_ID[p.id] = p));

	const clamp = (v, min, max) => Math.max(min, Math.min(max, v));

	// Distance between Sonic and the right end of the progress bar (px); 0 = flush with the end of the bar.
	// Adjustable live: tuiPets.setMargin(-6) pushes them further right, tuiPets.setMargin(10) = previous position.
	let barMargin = 0;

	// Top-right tile of the home page shortcuts grid (first row, right column), whatever its content:
	// each tile contains a small square image (about 48 px); the tile is the largest ancestor of that image that is shaped like a tile
	// (about 270 x 48 px); shelf cards (large images) are ignored
	function findTile() {
		const main = document.querySelector("#main-view");
		if (!main) return null;
		const root = main.querySelector('[data-testid="home-page"]') || main;
		const tiles = [];
		root.querySelectorAll("img").forEach(img => {
			const ir = img.getBoundingClientRect();
			if (ir.width < 40 || ir.width > 60 || ir.height < 40 || ir.height > 60) return;
			let el = img.parentElement;
			let best = null;
			for (let i = 0; el && el !== root && i < 6; i++, el = el.parentElement) {
				const r = el.getBoundingClientRect();
				if (r.height >= 40 && r.height <= 70 && r.width >= 220 && r.width <= 700) best = r;
				else if (best && r.height > 70) break;
			}
			if (best) tiles.push(best);
		});
		if (!tiles.length) return null;
		const top = Math.min(...tiles.map(r => r.top));
		return tiles.filter(r => Math.abs(r.top - top) < 6).reduce((a, b) => (b.left > a.left ? b : a));
	}

	// ---------- settings ----------
	function freshState() {
		return { v: 2, scaleSprites: 1, scaleCat: 1, scaleMiku: 1, scaleTanjiro: 1, scaleAmbers: 1, pets: {} };
	}
	function load() {
		try {
			const s = JSON.parse(localStorage.getItem(STORE));
			const st = freshState();
			if (s && typeof s === "object") {
				if (typeof s.scaleSprites === "number") st.scaleSprites = clamp(s.scaleSprites, 0.5, 2);
				if (typeof s.scaleCat === "number") st.scaleCat = clamp(s.scaleCat, 0.5, 2);
				if (typeof s.scaleMiku === "number") st.scaleMiku = clamp(s.scaleMiku, 0.5, 2);
				// v < 2: Tanjiro's old 100% size was 76x40; the default size is now 91x48 (the old 120%)
				if (s.v >= 2 && typeof s.scaleTanjiro === "number") st.scaleTanjiro = clamp(s.scaleTanjiro, 0.5, 2);
				if (typeof s.scaleAmbers === "number") st.scaleAmbers = clamp(s.scaleAmbers, 0.5, 2);
				if (s.pets && typeof s.pets === "object") st.pets = s.pets;
			}
			return st;
		} catch (e) {
			return freshState();
		}
	}
	let state = load();
	function save() {
		try {
			localStorage.setItem(STORE, JSON.stringify(state));
		} catch (e) {}
	}
	const petState = id => state.pets[id] || (state.pets[id] = {});

	// ---------- styles ----------
	const style = document.createElement("style");
	style.id = "tui-pets-style";
	style.textContent = `
		#tui-pets { position: fixed; inset: 0; pointer-events: none; z-index: 1000; }
		.tui-pet {
			position: absolute; display: none; background-repeat: no-repeat; background-size: 100% 100%;
			pointer-events: auto; cursor: grab; user-select: none; -webkit-user-select: none; touch-action: none;
		}
		.tui-pet--pixel { image-rendering: pixelated; }
		.tui-pet:hover, .tui-pet--drag { outline: 1px dashed var(--spice-border-active, #7aa2f7); }
		.tui-pet--drag { cursor: grabbing; }
		#tui-pets-panel {
			position: fixed; top: 100px; right: 24px; z-index: 1001; width: 260px; padding: 12px;
			background: var(--spice-main, #1a1b26); color: var(--spice-text, #a9b1d6);
			border: 1px solid var(--spice-border-active, #7aa2f7); border-radius: var(--border-radius, 0);
			font-size: 12px; box-shadow: 0 8px 24px rgba(0, 0, 0, .5);
		}
		#tui-pets-panel[hidden] { display: none; }
		#tui-pets-panel .tui-pets-title { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; font-weight: bold; }
		#tui-pets-panel label { display: flex; align-items: center; gap: 8px; margin: 6px 0; }
		#tui-pets-panel input[type=range] { flex: 1; }
		#tui-pets-panel button {
			background: transparent; color: inherit; border: 1px solid var(--spice-border-inactive, #565f89);
			border-radius: var(--border-radius, 0); padding: 3px 8px; cursor: pointer; font: inherit;
		}
		#tui-pets-panel button:hover { border-color: var(--spice-border-active, #7aa2f7); }
		#tui-pets-panel .tui-pets-actions { display: flex; gap: 6px; margin-top: 10px; flex-wrap: wrap; }
		#tui-pets-panel .tui-pets-hint { margin-top: 10px; opacity: .6; line-height: 1.4; }
	`;
	document.head.appendChild(style);

	// ---------- elements ----------
	const layer = document.createElement("div");
	layer.id = "tui-pets";
	const els = {};
	let dragging = null;

	PETS.forEach(p => {
		const el = document.createElement("div");
		el.className = "tui-pet" + (p.pixel ? " tui-pet--pixel" : "");
		el.dataset.pet = p.id;
		el.title = p.label + " - drag to move, double-click: original position, right-click: settings";
		el.style.backgroundImage = `url("${DATA[p.id]}")`;
		el.addEventListener("pointerdown", e => startDrag(e, p, el));
		el.addEventListener("dblclick", () => {
			delete petState(p.id).moved;
			save();
			layout();
		});
		el.addEventListener("contextmenu", e => {
			e.preventDefault();
			togglePanel(true);
		});
		layer.appendChild(el);
		els[p.id] = el;
	});
	document.body.appendChild(layer);

	// ---------- positions ----------
	function anchors() {
		const pos = document.querySelector('[data-testid="playback-position"]');
		const bar = pos && pos.nextElementSibling;
		const main = document.querySelector("#main-view");
		// last child of the search form = "browse" button; the vertical separator is at its left edge
		const trailing = document.querySelector('form[role="search"] > :last-child');
		return {
			bar: bar ? bar.getBoundingClientRect() : null,
			main: main ? main.getBoundingClientRect() : null,
			search: trailing ? trailing.getBoundingClientRect() : null
		};
	}
	// default positions (measured on the author's screenshots)
	function defaultPos(p, a) {
		// Miku: sitting on the top edge of the top-right tile of the home shortcuts grid, whatever its content
		// (box right edge 3 px beyond the tile's right edge, box bottom on the tile's top edge)
		if (p.id === "miku") {
			const tile = findTile();
			return tile ? { x: tile.right + 3 - p.w * state.scaleMiku, y: tile.top - p.h * state.scaleMiku } : null;
		}
		// Tanjiro: in the search bar, left of the vertical separator (23 px before the "browse" button), vertically centered
		if (p.id === "tanjiro") {
			const k = state.scaleTanjiro;
			return a.search && a.search.width ? { x: a.search.left - 23 - p.w * k, y: a.search.top + a.search.height / 2 - (p.h * k) / 2 } : null;
		}
		// Ambers: top-right corner of the Main frame
		if (p.id === "ambers") {
			return a.main ? { x: a.main.right - 3 - p.w * state.scaleAmbers, y: a.main.top + 4 } : null;
		}
		// Cat: 147 px from the right edge of Main
		if (p.id === "cat") {
			return a.main ? { x: a.main.right - 147 - p.w * state.scaleCat, y: a.main.top + 6 } : null;
		}
		if (!a.bar) return null;
		const s = state.scaleSprites;
		const bottom = a.bar.top + 7;
		const sonicX = a.bar.right - barMargin - BY_ID.sonic.w * s;
		const tailsX = sonicX - 5 * s - BY_ID.tails.w * s;
		const x = p.id === "sonic" ? sonicX : p.id === "tails" ? tailsX : a.bar.left + 4;
		return { x, y: bottom - p.h * s };
	}
	const isHome = () => !!document.querySelector('#main-view [data-testid="home-page"], #main-view .view-homeShortcutsGrid-shortcuts');

	function layout() {
		if (dragging) return;
		const a = anchors();
		const home = isHome();
		PETS.forEach(p => {
			const el = els[p.id];
			const st = petState(p.id);
			const scale = state[p.scaleKey];
			const w = Math.round(p.w * scale);
			const h = Math.round(p.h * scale);
			if (st.hidden || (p.homeOnly && !home)) {
				el.style.display = "none";
				return;
			}
			const pos = st.moved ? { x: st.fx * window.innerWidth, y: st.fy * window.innerHeight } : defaultPos(p, a);
			el.style.display = pos ? "block" : "none";
			if (!pos) return;
			el.style.width = w + "px";
			el.style.height = h + "px";
			el.style.left = Math.round(clamp(pos.x, 0, Math.max(0, window.innerWidth - w))) + "px";
			el.style.top = Math.round(clamp(pos.y, 0, Math.max(0, window.innerHeight - h))) + "px";
		});
	}

	// ---------- dragging ----------
	function startDrag(e, p, el) {
		if (e.button !== 0) return;
		e.preventDefault();
		const r = el.getBoundingClientRect();
		const dx = e.clientX - r.left;
		const dy = e.clientY - r.top;
		dragging = p.id;
		el.classList.add("tui-pet--drag");
		if (el.setPointerCapture && e.pointerId !== undefined) {
			try {
				el.setPointerCapture(e.pointerId);
			} catch (err) {}
		}
		const move = ev => {
			el.style.left = clamp(ev.clientX - dx, 0, Math.max(0, window.innerWidth - r.width)) + "px";
			el.style.top = clamp(ev.clientY - dy, 0, Math.max(0, window.innerHeight - r.height)) + "px";
		};
		const up = () => {
			el.removeEventListener("pointermove", move);
			el.removeEventListener("pointerup", up);
			el.removeEventListener("pointercancel", up);
			el.classList.remove("tui-pet--drag");
			const rr = el.getBoundingClientRect();
			const st = petState(p.id);
			st.moved = true;
			st.fx = rr.left / window.innerWidth;
			st.fy = rr.top / window.innerHeight;
			dragging = null;
			save();
		};
		el.addEventListener("pointermove", move);
		el.addEventListener("pointerup", up);
		el.addEventListener("pointercancel", up);
	}

	// ---------- panel ----------
	const panel = document.createElement("div");
	panel.id = "tui-pets-panel";
	panel.hidden = true;
	panel.innerHTML = `
		<div class="tui-pets-title"><span>Animated pets</span><button type="button" data-act="close" title="Close">x</button></div>
		<div class="tui-pets-list"></div>
		<label>Sprites <input type="range" min="50" max="200" step="5" data-scale="scaleSprites"></label>
		<label>Cat <input type="range" min="50" max="200" step="5" data-scale="scaleCat"></label>
		<label>Miku <input type="range" min="50" max="200" step="5" data-scale="scaleMiku"></label>
		<label>Tanjiro <input type="range" min="50" max="200" step="5" data-scale="scaleTanjiro"></label>
		<label>Ambers <input type="range" min="50" max="200" step="5" data-scale="scaleAmbers"></label>
		<div class="tui-pets-actions">
			<button type="button" data-act="reset">Reset positions</button>
			<button type="button" data-act="all">Hide / show all</button>
		</div>
		<div class="tui-pets-hint">Drag: move. Double-click a character: original position. Ctrl+Alt+P: open / close this panel.</div>`;
	const list = panel.querySelector(".tui-pets-list");
	PETS.forEach(p => {
		const row = document.createElement("label");
		row.innerHTML = `<input type="checkbox" data-pet="${p.id}"> <span>${p.label}</span>`;
		list.appendChild(row);
	});
	document.body.appendChild(panel);

	function syncPanel() {
		panel.querySelectorAll("input[data-pet]").forEach(i => (i.checked = !petState(i.dataset.pet).hidden));
		panel.querySelectorAll("input[data-scale]").forEach(i => (i.value = Math.round(state[i.dataset.scale] * 100)));
	}
	function togglePanel(forceOpen) {
		panel.hidden = forceOpen === true ? false : !panel.hidden;
		if (!panel.hidden) syncPanel();
	}
	panel.addEventListener("change", e => {
		const t = e.target;
		if (t.dataset.pet) petState(t.dataset.pet).hidden = !t.checked;
		save();
		layout();
	});
	panel.addEventListener("input", e => {
		const t = e.target;
		if (t.dataset.scale) {
			state[t.dataset.scale] = clamp(Number(t.value) / 100, 0.5, 2);
			save();
			layout();
		}
	});
	panel.addEventListener("click", e => {
		const act = e.target.dataset && e.target.dataset.act;
		if (act === "close") togglePanel(false);
		if (act === "reset") {
			PETS.forEach(p => delete petState(p.id).moved);
			save();
			layout();
		}
		if (act === "all") {
			const anyVisible = PETS.some(p => !petState(p.id).hidden);
			PETS.forEach(p => (petState(p.id).hidden = anyVisible));
			save();
			syncPanel();
			layout();
		}
	});
	document.addEventListener("keydown", e => {
		if (e.ctrlKey && e.altKey && (e.key === "p" || e.key === "P")) {
			e.preventDefault();
			togglePanel();
		}
	});

	// entry in the Spicetify profile menu (if available in this Spotify version)
	(function registerMenu(n) {
		try {
			if (window.Spicetify && Spicetify.Menu && Spicetify.Menu.Item) {
				new Spicetify.Menu.Item("Animated pets (Ctrl+Alt+P)", false, () => togglePanel()).register();
				return;
			}
		} catch (e) {}
		if (n < 20) setTimeout(() => registerMenu(n + 1), 500);
	})(0);

	// fallback console API: tuiPets.panel(), tuiPets.toggle("cat"), tuiPets.reset(), tuiPets.setMargin(n)
	window.tuiPets = {
		panel: () => togglePanel(),
		toggle: id => {
			if (!BY_ID[id]) return;
			petState(id).hidden = !petState(id).hidden;
			save();
			layout();
		},
		reset: () => {
			PETS.forEach(p => delete petState(p.id).moved);
			save();
			layout();
		},
		setMargin: n => {
			barMargin = Number(n) || 0;
			layout();
		},
		state: () => state
	};

	window.addEventListener("resize", layout);
	setInterval(layout, 500); // follows the playback bar and the home page (page changes, window size)
	layout();
})();
